import pandas as pd
import json
import re
from pathlib import Path
from jinja2 import Template
from datetime import datetime

# Load dataset
df = pd.read_csv('/app/benchmark/data.csv')

# Clean data
df['ECCENTRICITY'] = pd.to_numeric(df['ECCENTRICITY'], errors='coerce')
df['LAUNCH_YEAR'] = df['OBJECT_ID'].str[:4].astype(int)

# 1. KPIs
total_satellites = len(df)
leo_count = len(df[df['MEAN_MOTION'] > 14])
leo_share = (leo_count / total_satellites) * 100
starlink_count = len(df[df['OBJECT_NAME'].str.startswith('STARLINK', na=False)])
median_inclination = df['INCLINATION'].median()
post_2020 = len(df[df['LAUNCH_YEAR'] >= 2020])

kpis = {
    "total": f"{total_satellites:,}",
    "leo_share": f"{leo_share:.1f}%",
    "starlink_size": f"{starlink_count:,}",
    "median_inclination": f"{median_inclination:.1f}°",
    "post_2020": f"{post_2020:,}"
}

# 2. Orbital Regimes
def classify_orbit(row):
    mm = row['MEAN_MOTION']
    ecc = row['ECCENTRICITY']
    if ecc >= 0.25:
        return 'HEO'
    elif mm > 14:
        return 'LEO'
    elif 0.9 <= mm <= 1.1:
        return 'GEO'
    else:
        return 'MEO'

df['ORBIT_REGIME'] = df.apply(classify_orbit, axis=1)
regime_counts = df['ORBIT_REGIME'].value_counts()
orbit_labels = regime_counts.index.tolist()
orbit_values = regime_counts.values.tolist()

# 3. Constellations
def get_prefix(name):
    m = re.match(r'^([A-Z]+)', str(name))
    return m.group(1) if m else str(name).split()[0]

df['CONSTELLATION'] = df['OBJECT_NAME'].apply(get_prefix)
const_counts = df['CONSTELLATION'].value_counts().head(10)
const_labels = const_counts.index.tolist()
const_values = const_counts.values.tolist()

# 4. Launch Trends
launch_counts = df['LAUNCH_YEAR'].value_counts().sort_index()
launch_counts = launch_counts[launch_counts.index >= 1990] # Filter reasonable years
launch_labels = launch_counts.index.tolist()
launch_values = launch_counts.values.tolist()

# 5. Inclination Bins
inc_bins = pd.cut(df['INCLINATION'], bins=range(0, 101, 10))
inc_counts = inc_bins.value_counts().sort_index()
inc_labels = [f"{int(b.left)}-{int(b.right)}°" for b in inc_counts.index]
inc_values = inc_counts.values.tolist()

# Output data structure
chart_data = {
    "orbit_labels": json.dumps(orbit_labels),
    "orbit_values": json.dumps(orbit_values),
    "const_labels": json.dumps(const_labels),
    "const_values": json.dumps(const_values),
    "launch_labels": json.dumps(launch_labels),
    "launch_values": json.dumps(launch_values),
    "inc_labels": json.dumps(inc_labels),
    "inc_values": json.dumps(inc_values),
}

# Jinja2 Template
html_template = """<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Active Satellites in Earth Orbit - 2026 Catalog Analysis</title>
    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
    <style>
        :root {
            --bg-color: #f8fafc;
            --card-bg: #ffffff;
            --text-main: #1e293b;
            --text-muted: #64748b;
            --primary: #2563eb;
            --secondary: #3b82f6;
            --border: #e2e8f0;
        }
        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            background-color: var(--bg-color);
            color: var(--text-main);
            line-height: 1.6;
            margin: 0;
            padding: 0;
        }
        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 40px 20px;
        }
        header {
            text-align: center;
            margin-bottom: 40px;
        }
        h1 {
            font-size: 2.5rem;
            margin-bottom: 10px;
            color: #0f172a;
        }
        .subtitle {
            font-size: 1.2rem;
            color: var(--text-muted);
        }
        .section {
            background: var(--card-bg);
            border-radius: 12px;
            padding: 30px;
            margin-bottom: 30px;
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
            border: 1px solid var(--border);
        }
        h2 {
            margin-top: 0;
            border-bottom: 2px solid var(--bg-color);
            padding-bottom: 10px;
            color: #0f172a;
        }
        .kpi-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 20px;
            margin-top: 20px;
        }
        .kpi-card {
            background: var(--bg-color);
            padding: 20px;
            border-radius: 8px;
            text-align: center;
            border: 1px solid var(--border);
        }
        .kpi-value {
            font-size: 2.2rem;
            font-weight: 700;
            color: var(--primary);
            margin: 10px 0;
        }
        .kpi-label {
            font-size: 0.9rem;
            font-weight: 600;
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 0.05em;
        }
        .chart-container {
            position: relative;
            height: 400px;
            width: 100%;
            margin-top: 20px;
        }
        .grid-2 {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 30px;
        }
        @media (max-width: 768px) {
            .grid-2 {
                grid-template-columns: 1fr;
            }
        }
        p {
            font-size: 1.05rem;
        }
    </style>
</head>
<body>

<div class="container">
    <header>
        <h1>Active Satellites in Earth Orbit</h1>
        <div class="subtitle">2026 Catalog Analysis Report</div>
    </header>

    <div class="section" id="overview">
        <h2>Catalog Overview & Key Figures</h2>
        <p>This report analyzes the population of 14,875 active satellites currently in Earth orbit, based on the latest 2026 NORAD catalog data. The orbital environment is experiencing unprecedented growth, largely driven by mega-constellations in Low Earth Orbit (LEO).</p>

        <div class="kpi-grid">
            <div class="kpi-card">
                <div class="kpi-label">Total Active Satellites</div>
                <div class="kpi-value">{{ kpis.total }}</div>
            </div>
            <div class="kpi-card">
                <div class="kpi-label">LEO Share</div>
                <div class="kpi-value">{{ kpis.leo_share }}</div>
            </div>
            <div class="kpi-card">
                <div class="kpi-label">Starlink Size</div>
                <div class="kpi-value">{{ kpis.starlink_size }}</div>
            </div>
            <div class="kpi-card">
                <div class="kpi-label">Median Inclination</div>
                <div class="kpi-value">{{ kpis.median_inclination }}</div>
            </div>
            <div class="kpi-card">
                <div class="kpi-label">Launched Since 2020</div>
                <div class="kpi-value">{{ kpis.post_2020 }}</div>
            </div>
        </div>
    </div>

    <div class="section" id="launch-trends">
        <h2>Launch Year Trends</h2>
        <p>The most defining characteristic of the current space era is the exponential acceleration in launch activity since 2020. Over 90% of currently active satellites were launched in the last 6 years.</p>
        <div class="chart-container">
            <canvas id="launchChart"></canvas>
        </div>
    </div>

    <div class="grid-2">
        <div class="section" id="orbit-regime">
            <h2>Orbital Regime Classification</h2>
            <p>Using Mean Motion thresholds (>14 rev/day for LEO, ~1.0 for GEO), it is clear that LEO dominates the active satellite population, driven by broadband constellations.</p>
            <div class="chart-container">
                <canvas id="orbitChart"></canvas>
            </div>
        </div>

        <div class="section" id="constellation-analysis">
            <h2>Major Constellation Breakdown</h2>
            <p>SpaceX's Starlink dominates the active satellite catalog, making up roughly two-thirds of the total population. This single operator significantly skews overall orbital distributions.</p>
            <div class="chart-container">
                <canvas id="constChart"></canvas>
            </div>
        </div>
    </div>

    <div class="section" id="orbital-characteristics">
        <h2>Orbital Parameter Deep Dive</h2>
        <p>Analyzing the inclination of active satellites reveals distinct orbital "shells." The median inclination is driven heavily by Starlink's primary operational inclination of ~53 degrees.</p>
        <div class="chart-container">
            <canvas id="incChart"></canvas>
        </div>
    </div>

    <div class="section" id="conclusions">
        <h2>Key Takeaways & Outlook</h2>
        <p><strong>1. Mega-Constellation Dominance:</strong> Starlink is by far the largest single factor in the current orbital environment, representing {{ kpis.starlink_size }} satellites. Any regulatory or spectrum policy must account for the outsized impact of a single operator's architecture.</p>
        <p><strong>2. The LEO Congestion:</strong> With {{ kpis.leo_share }} of all satellites residing in Low Earth Orbit, space traffic management and debris mitigation in the LEO regime are critical priorities. GEO and MEO represent a much smaller, largely static, strategic asset base.</p>
        <p><strong>3. Unprecedented Growth Rate:</strong> The fact that {{ kpis.post_2020 }} active satellites were launched since 2020 demonstrates a paradigm shift in space access. The transition from large, exquisite satellites to proliferated small-satellite architectures is complete.</p>
    </div>
</div>

<script>
    // Theme colors
    const colors = ['#2563eb', '#3b82f6', '#60a5fa', '#93c5fd', '#bfdbfe', '#e0e7ff', '#c7d2fe', '#a5b4fc', '#818cf8', '#6366f1'];

    // Launch Trends Chart
    new Chart(document.getElementById('launchChart'), {
        type: 'line',
        data: {
            labels: {{ chart_data.launch_labels|safe }},
            datasets: [{
                label: 'Active Satellites Launched',
                data: {{ chart_data.launch_values|safe }},
                borderColor: '#2563eb',
                backgroundColor: 'rgba(37, 99, 235, 0.1)',
                borderWidth: 2,
                fill: true,
                tension: 0.3
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: { display: false }
            },
            scales: {
                y: { beginAtZero: true }
            }
        }
    });

    // Orbit Regime Chart
    new Chart(document.getElementById('orbitChart'), {
        type: 'doughnut',
        data: {
            labels: {{ chart_data.orbit_labels|safe }},
            datasets: [{
                data: {{ chart_data.orbit_values|safe }},
                backgroundColor: ['#2563eb', '#10b981', '#f59e0b', '#ef4444'],
                borderWidth: 0
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: { position: 'right' }
            }
        }
    });

    // Constellation Chart
    new Chart(document.getElementById('constChart'), {
        type: 'bar',
        data: {
            labels: {{ chart_data.const_labels|safe }},
            datasets: [{
                label: 'Satellites',
                data: {{ chart_data.const_values|safe }},
                backgroundColor: '#3b82f6',
                borderRadius: 4
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: { display: false }
            },
            scales: {
                y: { beginAtZero: true }
            }
        }
    });

    // Inclination Chart
    new Chart(document.getElementById('incChart'), {
        type: 'bar',
        data: {
            labels: {{ chart_data.inc_labels|safe }},
            datasets: [{
                label: 'Satellites by Inclination',
                data: {{ chart_data.inc_values|safe }},
                backgroundColor: '#8b5cf6',
                borderRadius: 4
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: { display: false }
            },
            scales: {
                y: { beginAtZero: true }
            }
        }
    });
</script>
</body>
</html>
"""

template = Template(html_template)
final_html = template.render(kpis=kpis, chart_data=chart_data)

output_dir = Path('/app/output')
output_dir.mkdir(parents=True, exist_ok=True)
output_file = output_dir / 'final_report.html'
output_file.write_text(final_html)

print(f"Successfully generated {output_file}")
